import json
from collections import defaultdict

# === 1. Load Expert SFT data ===
with open('eto_repo/data/alfworld_sft.json') as f:
    expert_data = json.load(f)
print(f'Expert SFT total entries: {len(expert_data)}')

# Extract game_file as task identifier
# Normalize: extract the task folder name from game_file path
def extract_task_name(game_file):
    # e.g. .../train/pick_clean_then_place_in_recep-Spoon-None-DiningTable-18/trial_.../game.tw-pddl
    parts = game_file.split('/')
    for i, p in enumerate(parts):
        if p in ('train', 'valid', 'test'):
            if i+1 < len(parts):
                return parts[i+1]  # task folder name
    return game_file

def extract_task_type_from_name(task_name):
    # ALFWorld 6 task types
    types = ['pick_and_place', 'pick_clean_then_place', 'pick_heat_then_place', 
             'pick_cool_then_place', 'look_at_obj', 'pick_two_obj']
    for t in types:
        if task_name.startswith(t):
            return t
    return 'unknown'

# Expert tasks - check if entries have game_file or other fields
print(f'Expert first entry keys: {list(expert_data[0].keys())}')

# Check data format
expert_has_game_file = 'game_file' in expert_data[0]
expert_has_conversations = 'conversations' in expert_data[0]
print(f'Has game_file: {expert_has_game_file}')

if expert_has_game_file:
    expert_tasks = {}
    for e in expert_data:
        task_name = extract_task_name(e['game_file'])
        task_type = e.get('task_type', extract_task_type_from_name(task_name))
        reward = e.get('reward', True)  # SFT data assumed successful
        expert_tasks[task_name] = {'task_type': task_type, 'reward': reward, 'game_file': e['game_file']}

    expert_success = {k: v for k, v in expert_tasks.items() if v['reward'] != False}
    print(f'Expert unique tasks: {len(expert_tasks)}')
    print(f'Expert successful tasks (reward!=False): {len(expert_success)}')

    # Expert task type distribution
    expert_type_dist = defaultdict(int)
    for v in expert_success.values():
        expert_type_dist[v['task_type']] += 1
    print(f'\nExpert task type distribution (successful only):')
    for t, c in sorted(expert_type_dist.items()):
        print(f'  {t}: {c}')
else:
    print('ERROR: No game_file field in expert data')
    # Try to find task identifier
    print(json.dumps(expert_data[0], indent=2)[:500])

# === 2. Load v5 failure trajectories ===
v5_entries = []
for path in ['data/trajectories_v5_cuda0/train.jsonl', 'data/trajectories_v5_cuda1/train.jsonl']:
    with open(path) as f:
        for line in f:
            v5_entries.append(json.loads(line))

print(f'\n=== V5 Trajectories ===')
print(f'Total v5 entries: {len(v5_entries)}')

v5_tasks = {}
for e in v5_entries:
    task_name = extract_task_name(e['game_file'])
    task_type = e.get('task_type', extract_task_type_from_name(task_name))
    reward = e.get('reward', False)
    if task_name not in v5_tasks:
        v5_tasks[task_name] = {'task_type': task_type, 'reward': reward, 'game_file': e['game_file']}
    else:
        # Keep track if any attempt succeeded
        if reward:
            v5_tasks[task_name]['reward'] = True

v5_failures = {k: v for k, v in v5_tasks.items() if not v['reward']}
v5_successes = {k: v for k, v in v5_tasks.items() if v['reward']}

print(f'V5 unique tasks: {len(v5_tasks)}')
print(f'V5 failures: {len(v5_failures)}')
print(f'V5 successes: {len(v5_successes)}')

# V5 task type distribution
v5_type_dist = defaultdict(lambda: {'fail': 0, 'success': 0})
for k, v in v5_tasks.items():
    if v['reward']:
        v5_type_dist[v['task_type']]['success'] += 1
    else:
        v5_type_dist[v['task_type']]['fail'] += 1

print(f'\nV5 task type distribution:')
for t, c in sorted(v5_type_dist.items()):
    print(f'  {t}: fail={c[\"fail\"]}, success={c[\"success\"]}')

# === 3. Compute Overlap ===
expert_task_set = set(expert_success.keys())
v5_failure_set = set(v5_failures.keys())

overlap = expert_task_set & v5_failure_set
overlap_pct = len(overlap) / len(v5_failure_set) * 100 if v5_failure_set else 0

print(f'\n=== OVERLAP ANALYSIS ===')
print(f'Expert successful tasks: {len(expert_task_set)}')
print(f'V5 failure tasks: {len(v5_failure_set)}')
print(f'Overlap: {len(overlap)} ({overlap_pct:.1f}% of v5 failures)')

if overlap_pct < 50:
    print(f'\n*** RED ALERT: Overlap is only {overlap_pct:.1f}% (< 50%) ***')

# === 4. Per task type overlap ===
print(f'\n=== PER TASK TYPE OVERLAP ===')
type_overlap = defaultdict(lambda: {'expert': 0, 'v5_fail': 0, 'overlap': 0})
for k, v in expert_success.items():
    type_overlap[v['task_type']]['expert'] += 1
for k, v in v5_failures.items():
    type_overlap[v['task_type']]['v5_fail'] += 1
    if k in expert_task_set:
        type_overlap[v['task_type']]['overlap'] += 1

print(f'{'Task Type':<30} {'Expert':>8} {'V5 Fail':>8} {'Overlap':>8} {'Overlap%':>10}')
print('-' * 70)
for t in sorted(type_overlap.keys()):
    d = type_overlap[t]
    pct = d['overlap'] / d['v5_fail'] * 100 if d['v5_fail'] > 0 else 0
    flag = ' *** LOW' if pct < 50 else ''
    print(f'{t:<30} {d[\"expert\"]:>8} {d[\"v5_fail\"]:>8} {d[\"overlap\"]:>8} {pct:>9.1f}%{flag}')

# === 5. Show overlap details ===
print(f'\n=== OVERLAPPING TASKS ({len(overlap)}) ===')
for t in sorted(overlap):
    tt = v5_failures[t]['task_type']
    print(f'  [{tt}] {t}')

# === 6. Non-overlapping v5 failures ===
non_overlap = v5_failure_set - expert_task_set
print(f'\n=== NON-OVERLAPPING V5 FAILURES ({len(non_overlap)}) ===')
for t in sorted(non_overlap):
    tt = v5_failures[t]['task_type']
    print(f'  [{tt}] {t}')

# === 7. Check if expert uses train split and v5 also uses train split ===
expert_splits = defaultdict(int)
for e in expert_data:
    gf = e['game_file']
    if '/train/' in gf:
        expert_splits['train'] += 1
    elif '/valid/' in gf:
        expert_splits['valid'] += 1
    elif '/test/' in gf:
        expert_splits['test'] += 1
    else:
        expert_splits['other'] += 1

v5_splits = defaultdict(int)
for e in v5_entries:
    gf = e['game_file']
    if '/train/' in gf:
        v5_splits['train'] += 1
    elif '/valid/' in gf:
        v5_splits['valid'] += 1
    elif '/test/' in gf:
        v5_splits['test'] += 1
    else:
        v5_splits['other'] += 1

print(f'\n=== DATA SPLIT DISTRIBUTION ===')
print(f'Expert splits: {dict(expert_splits)}')
print(f'V5 splits: {dict(v5_splits)}')
"
